--liquibase formatted sql
--changeset fin-calc:052a dbms:postgresql splitStatements:true
-- User-supplied research formula catalog. This is NON-EXECUTABLE evidence,
-- NOT an approved method formula and NOT a CalcPlan artifact.
CREATE TABLE fin_calc.methodology_research_candidate (
 candidate_code varchar(80) PRIMARY KEY,
 -- fin_lib form definitions are populated by Java ApplicationRunner AFTER Liquibase.
 -- Candidate research is rejoined and validated against the populated catalog
 -- at read/qualification time, not via a premature bootstrap-time FK.
 owner_form_code varchar(128) NOT NULL
   CHECK(owner_form_code ~ '^[A-Z0-9_-]{2,128} related_form_codes_jsonb jsonb NOT NULL CHECK(jsonb_typeof(related_form_codes_jsonb)='array'),
 source_section smallint NOT NULL CHECK(source_section BETWEEN 1 AND 12),
 operation_family varchar(40) NOT NULL,
 formula_text text NOT NULL CHECK(length(trim(formula_text))>0),
 review_status varchar(40) NOT NULL CHECK(review_status IN
  ('MISSING_INPUT_CONTRACT','REQUIRES_FINANCIAL_POLICY',
   'CORRECTED_FROM_SOURCE','NON_EXECUTABLE_DISCLOSURE')),
 blockers_text text NOT NULL,
 uploaded_source_sha256 char(64) NOT NULL
   CHECK(uploaded_source_sha256 ~ '^[0-9a-f]{64}$'),
 source_repository_path text NOT NULL,
 financially_approved boolean NOT NULL DEFAULT false CHECK(NOT financially_approved),
 production_admitted boolean NOT NULL DEFAULT false CHECK(NOT production_admitted),
 created_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
CREATE INDEX idx_method_research_form
 ON fin_calc.methodology_research_candidate(owner_form_code,operation_family);
--changeset fin-calc:052b dbms:postgresql splitStatements:true
CREATE TRIGGER trg_research_candidate_immutable BEFORE UPDATE OR DELETE
 ON fin_calc.methodology_research_candidate FOR EACH ROW
 EXECUTE FUNCTION fin_fact.reject_immutable_mutation();
CREATE TRIGGER trg_research_candidate_no_truncate BEFORE TRUNCATE
 ON fin_calc.methodology_research_candidate FOR EACH STATEMENT
 EXECUTE FUNCTION fin_fact.reject_immutable_mutation();

--changeset fin-calc:052c dbms:postgresql splitStatements:true
