 ('C02_PAST_DUE_DAYS','C02','["C02"]'::jsonb,2,'AGING','max(0, asOf_date - effective_due_date) DAYS','CORRECTED_FROM_SOURCE','days are not overdue money, requires allocation and due-effective date','de698223e65c64ce887ee30796a658b2706278e5ff7469a257f06b8d779d35c3','docs/sources/FIN-CALC154-USER-FORMULA-RESEARCH-2026-11-20.md'),
 ('C02_OFFSET_CHECK','C02','["C02","C11"]'::jsonb,2,'ELIGIBILITY','payables - offset_eligible_advances IF legal_right AND net_settlement_intent AND eligible_instruments','REQUIRES_FINANCIAL_POLICY','IAS 32 conditional; nonfinancial prepayments not automatically IAS32 eligible','de698223e65c64ce887ee30796a658b2706278e5ff7469a257f06b8d779d35c3','docs/sources/FIN-CALC154-USER-FORMULA-RESEARCH-2026-11-20.md'),
 ('C03_WEIGHTED_AVERAGE','C03','["C03"]'::jsonb,3,'COST_FLOW','(opening_stock_cost + receipts_cost) / (opening_quantity + receipts_quantity)','MISSING_INPUT_CONTRACT','inventory lots and purchase prices not in C03 physical fields','de698223e65c64ce887ee30796a658b2706278e5ff7469a257f06b8d779d35c3','docs/sources/FIN-CALC154-USER-FORMULA-RESEARCH-2026-11-20.md'),
 ('C03_FIFO','C03','["C03"]'::jsonb,3,'COST_FLOW','sum(consumed_quantity_per_oldest_available_lot * lot_unit_cost)','MISSING_INPUT_CONTRACT','dated purchases, consumption and lot-level source contract needed','de698223e65c64ce887ee30796a658b2706278e5ff7469a257f06b8d779d35c3','docs/sources/FIN-CALC154-USER-FORMULA-RESEARCH-2026-11-20.md'),
 ('C03_NRV','C03','["C03"]'::jsonb,3,'VALUATION','estimated_selling_price - completion_costs - selling_costs','MISSING_INPUT_CONTRACT','per-item forecasts and expenses missing; estimates need policy','de698223e65c64ce887ee30796a658b2706278e5ff7469a257f06b8d779d35c3','docs/sources/FIN-CALC154-USER-FORMULA-RESEARCH-2026-11-20.md'),
 ('C03_COST_NRV_MIN','C03','["C03"]'::jsonb,3,'VALUATION','min(item_cost, item_NRV); write_down = max(0, item_cost-item_NRV)','REQUIRES_FINANCIAL_POLICY','apply to relevant individual items, not gross category offset','de698223e65c64ce887ee30796a658b2706278e5ff7469a257f06b8d779d35c3','docs/sources/FIN-CALC154-USER-FORMULA-RESEARCH-2026-11-20.md'),
 ('C04_STRAIGHT_LINE','C04','["C04"]'::jsonb,4,'DEPRECIATION','(depreciable_cost - residual_value) / useful_life_periods','MISSING_INPUT_CONTRACT','residual value, life, asset components and in-service date needed','de698223e65c64ce887ee30796a658b2706278e5ff7469a257f06b8d779d35c3','docs/sources/FIN-CALC154-USER-FORMULA-RESEARCH-2026-11-20.md'),
 ('C04_DECLINING_BALANCE','C04','["C04"]'::jsonb,4,'DEPRECIATION','opening_carrying_value * approved_declining_rate','REQUIRES_FINANCIAL_POLICY','declining rate and residual-value controls are entity policy','de698223e65c64ce887ee30796a658b2706278e5ff7469a257f06b8d779d35c3','docs/sources/FIN-CALC154-USER-FORMULA-RESEARCH-2026-11-20.md'),
 ('C04_IMPAIRMENT','C04','["C04","F01"]'::jsonb,4,'IMPAIRMENT','max(0, carrying_amount - max(fair_value_less_cost_of_disposal,value_in_use))','MISSING_INPUT_CONTRACT','fair value, value in use, CGU attribution and discounting missing','de698223e65c64ce887ee30796a658b2706278e5ff7469a257f06b8d779d35c3','docs/sources/FIN-CALC154-USER-FORMULA-RESEARCH-2026-11-20.md'),
 ('C05_NOMINAL_INTEREST','C05','["C05","P04"]'::jsonb,5,'INTEREST','principal_opening * nominal_period_rate','REQUIRES_FINANCIAL_POLICY','day count, dates, interest accrual and principal vs carrying amount needed','de698223e65c64ce887ee30796a658b2706278e5ff7469a257f06b8d779d35c3','docs/sources/FIN-CALC154-USER-FORMULA-RESEARCH-2026-11-20.md'),
 ('C05_EIR','C05','["C05","P04"]'::jsonb,5,'INTEREST','solve(initial_net_carrying_amount = sum(contractual_cashflow_t / (1+EIR)^t))','MISSING_INPUT_CONTRACT','dated contractual cash flows, fees, transaction costs and modification basis needed','de698223e65c64ce887ee30796a658b2706278e5ff7469a257f06b8d779d35c3','docs/sources/FIN-CALC154-USER-FORMULA-RESEARCH-2026-11-20.md'),
 ('P04_ANNUITY','P04','["C05","P04"]'::jsonb,5,'AMORTIZATION','P*r*(1+r)^n / ((1+r)^n - 1)','REQUIRES_FINANCIAL_POLICY','rate period and payment dates, rate zero branch, schedule and rounding needed','de698223e65c64ce887ee30796a658b2706278e5ff7469a257f06b8d779d35c3','docs/sources/FIN-CALC154-USER-FORMULA-RESEARCH-2026-11-20.md'),
 ('P04_EQUAL_PRINCIPAL','P04','["C05","P04"]'::jsonb,5,'AMORTIZATION','principal_repayment=P/n; interest_t=opening_principal_t * period_rate','REQUIRES_FINANCIAL_POLICY','partial period, final payment adjustment, fees and contract-specific schedule','de698223e65c64ce887ee30796a658b2706278e5ff7469a257f06b8d779d35c3','docs/sources/FIN-CALC154-USER-FORMULA-RESEARCH-2026-11-20.md'),
 ('C07_RECOGNIZED_NET_SALES','C07','["C07","F02"]'::jsonb,6,'REVENUE','recognized_gross_sales - eligible_returns - discounts - variable_consideration_adjustments','MISSING_INPUT_CONTRACT','C07 has grossSales and returns but no discount and variable consideration fields','de698223e65c64ce887ee30796a658b2706278e5ff7469a257f06b8d779d35c3','docs/sources/FIN-CALC154-USER-FORMULA-RESEARCH-2026-11-20.md'),
 ('C07_EXPECTED_CONSIDERATION','C07','["C07","F02"]'::jsonb,6,'REVENUE','sum(scenario_probability * scenario_consideration)','MISSING_INPUT_CONTRACT','IFRS 15 constraint, scenario probabilities, contract terms missing','de698223e65c64ce887ee30796a658b2706278e5ff7469a257f06b8d779d35c3','docs/sources/FIN-CALC154-USER-FORMULA-RESEARCH-2026-11-20.md'),
 ('F02_CORRECTED_GROSS_MARGIN','F02','["C07","F02"]'::jsonb,6,'RATIO','(recognized_net_revenue - recognized_COGS) / recognized_net_revenue','REQUIRES_FINANCIAL_POLICY','zero denominator, period, gross/net matching','de698223e65c64ce887ee30796a658b2706278e5ff7469a257f06b8d779d35c3','docs/sources/FIN-CALC154-USER-FORMULA-RESEARCH-2026-11-20.md'),
 ('C09_CAPITALIZATION_RECLASS','C09','["C08","C09","P02"]'::jsonb,7,'RECLASS','expense_original - approved_capitalized_cost + eligible_amortization','REQUIRES_FINANCIAL_POLICY','asset recognition basis, proof, life and amortization absent','de698223e65c64ce887ee30796a658b2706278e5ff7469a257f06b8d779d35c3','docs/sources/FIN-CALC154-USER-FORMULA-RESEARCH-2026-11-20.md'),
 ('F03_CFO_INDIRECT','F03','["F03","P03"]'::jsonb,8,'CASH_FLOW','net_profit + noncash_adjustments - delta_working_capital + other_operating_adjustments','MISSING_INPUT_CONTRACT','working capital change must reconcile cash and noncash items; source insufficient','de698223e65c64ce887ee30796a658b2706278e5ff7469a257f06b8d779d35c3','docs/sources/FIN-CALC154-USER-FORMULA-RESEARCH-2026-11-20.md'),
 ('P03_CFO_DIRECT','P03','["F03","P03"]'::jsonb,8,'CASH_FLOW','customer_cash_received - supplier_cash_paid - operating_cash_costs - taxes_paid','MISSING_INPUT_CONTRACT','cash payment classification and exact settlement period needed','de698223e65c64ce887ee30796a658b2706278e5ff7469a257f06b8d779d35c3','docs/sources/FIN-CALC154-USER-FORMULA-RESEARCH-2026-11-20.md'),
 ('F03_WORKING_CAPITAL_DELTA','F03','["C01","C02","C03","F03"]'::jsonb,8,'BRIDGE','delta_AR + delta_inventory - delta_AP (cash-flow adjusted)','REQUIRES_FINANCIAL_POLICY','exclude noncash movements and FX, do not equate raw delta with cashflow','de698223e65c64ce887ee30796a658b2706278e5ff7469a257f06b8d779d35c3','docs/sources/FIN-CALC154-USER-FORMULA-RESEARCH-2026-11-20.md'),
 ('P06_DSO','P06','["P01","P02","P06"]'::jsonb,9,'RATIO','average_AR / period_recognized_revenue * days_in_basis','REQUIRES_FINANCIAL_POLICY','day count, opening/closing stocks, revenue basis','de698223e65c64ce887ee30796a658b2706278e5ff7469a257f06b8d779d35c3','docs/sources/FIN-CALC154-USER-FORMULA-RESEARCH-2026-11-20.md'),
 ('P06_FORECAST_AR','P06','["P01","P02","P06"]'::jsonb,9,'FORECAST','DSO * forecast_net_revenue / approved_days_in_period','REQUIRES_FINANCIAL_POLICY','one forecasting approach chosen across scenarios','de698223e65c64ce887ee30796a658b2706278e5ff7469a257f06b8d779d35c3','docs/sources/FIN-CALC154-USER-FORMULA-RESEARCH-2026-11-20.md'),
 ('P06_DPO','P06','["P01","P02","P06"]'::jsonb,9,'RATIO','average_AP / period_COGS * days_in_basis','REQUIRES_FINANCIAL_POLICY','asOf vs interval, expenses basis and day count','de698223e65c64ce887ee30796a658b2706278e5ff7469a257f06b8d779d35c3','docs/sources/FIN-CALC154-USER-FORMULA-RESEARCH-2026-11-20.md'),
 ('P06_FORECAST_AP','P06','["P01","P02","P06"]'::jsonb,9,'FORECAST','DPO * forecast_COGS / approved_days_in_period','REQUIRES_FINANCIAL_POLICY','one forecasting approach chosen across scenarios','de698223e65c64ce887ee30796a658b2706278e5ff7469a257f06b8d779d35c3','docs/sources/FIN-CALC154-USER-FORMULA-RESEARCH-2026-11-20.md'),
 ('P07_FCFF','P07','["P07"]'::jsonb,9,'DCF','EBIT*(1-tax_rate) + noncash_depreciation - CAPEX - delta_NWC','MISSING_INPUT_CONTRACT','EBIT tax convention and signed CAPEX/NWC from source revisions','de698223e65c64ce887ee30796a658b2706278e5ff7469a257f06b8d779d35c3','docs/sources/FIN-CALC154-USER-FORMULA-RESEARCH-2026-11-20.md'),
 ('P07_FCFE','P07','["P07"]'::jsonb,9,'DCF','net_income + noncash_depreciation - CAPEX - delta_NWC + net_borrowing','MISSING_INPUT_CONTRACT','same assumptions and equity flow adjustments','de698223e65c64ce887ee30796a658b2706278e5ff7469a257f06b8d779d35c3','docs/sources/FIN-CALC154-USER-FORMULA-RESEARCH-2026-11-20.md'),
 ('P07_ENTERPRISE_VALUE','P07','["P07"]'::jsonb,9,'DCF','sum(FCFF_t / (1+WACC)^t) + TV_n / (1+WACC)^n','MISSING_INPUT_CONTRACT','requires FCFF/WACC typed compatibility and dated flows','de698223e65c64ce887ee30796a658b2706278e5ff7469a257f06b8d779d35c3','docs/sources/FIN-CALC154-USER-FORMULA-RESEARCH-2026-11-20.md'),
 ('P07_EQUITY_VALUE','P07','["P07"]'::jsonb,9,'DCF','sum(FCFE_t / (1+Ke)^t) + TV_n / (1+Ke)^n','MISSING_INPUT_CONTRACT','requires FCFE/Ke typed compatibility and dated flows','de698223e65c64ce887ee30796a658b2706278e5ff7469a257f06b8d779d35c3','docs/sources/FIN-CALC154-USER-FORMULA-RESEARCH-2026-11-20.md'),
 ('P07_GORDON_TV','P07','["P07"]'::jsonb,9,'DCF','CF_n*(1+g)/(discount_rate-g)','REQUIRES_FINANCIAL_POLICY','g < rate, sustainable growth, terminal period and units','de698223e65c64ce887ee30796a658b2706278e5ff7469a257f06b8d779d35c3','docs/sources/FIN-CALC154-USER-FORMULA-RESEARCH-2026-11-20.md'),
 ('P07_WACC','P07','["P07"]'::jsonb,9,'DCF','(E/(E+D))*Ke + (D/(E+D))*Kd*(1-tax_rate)','REQUIRES_FINANCIAL_POLICY','market values of capital, debt tax shield and rate sources','de698223e65c64ce887ee30796a658b2706278e5ff7469a257f06b8d779d35c3','docs/sources/FIN-CALC154-USER-FORMULA-RESEARCH-2026-11-20.md'),
 ('P07_IRR','P07','["P07"]'::jsonb,9,'IRR','find roots for NPV(r)=sum(CF_t/(1+r)^t)=0','MISSING_INPUT_CONTRACT','sign changes, multiple roots, periodic vs irregular dates; do not presume single IRR','de698223e65c64ce887ee30796a658b2706278e5ff7469a257f06b8d779d35c3','docs/sources/FIN-CALC154-USER-FORMULA-RESEARCH-2026-11-20.md'),
 ('P08_SCENARIO_EXPECTED_NPV','P08','["P07","P08"]'::jsonb,10,'SCENARIO','sum(scenario_probability * scenario_NPV)','REQUIRES_FINANCIAL_POLICY','scenario source, coherent basis, probability normalization','de698223e65c64ce887ee30796a658b2706278e5ff7469a257f06b8d779d35c3','docs/sources/FIN-CALC154-USER-FORMULA-RESEARCH-2026-11-20.md'),
 ('P09_CFADS','P09','["P04","P09"]'::jsonb,10,'DEBT_SERVICE','cash_available_for_debt_service (per agreement cash waterfall)','REQUIRES_FINANCIAL_POLICY','EBITDA - taxes - CAPEX - deltaNWC only a candidate; actual covenants may differ','de698223e65c64ce887ee30796a658b2706278e5ff7469a257f06b8d779d35c3','docs/sources/FIN-CALC154-USER-FORMULA-RESEARCH-2026-11-20.md'),
 ('P09_DSCR','P09','["P04","P09"]'::jsonb,10,'RATIO','CFADS / contractual_cash_interest_and_principal_due_for_period','REQUIRES_FINANCIAL_POLICY','cash debt service vs accounting EIR interest, fees and zero denominator','de698223e65c64ce887ee30796a658b2706278e5ff7469a257f06b8d779d35c3','docs/sources/FIN-CALC154-USER-FORMULA-RESEARCH-2026-11-20.md'),
 ('X_C05_F01','F01','["C05","F01"]'::jsonb,11,'RECONCILE','loan_liability_on_F01 == source_C05_carrying_amount_with_accruals','MISSING_INPUT_CONTRACT','do not add accrued interest twice','de698223e65c64ce887ee30796a658b2706278e5ff7469a257f06b8d779d35c3','docs/sources/FIN-CALC154-USER-FORMULA-RESEARCH-2026-11-20.md'),
 ('X_C01_F03','F03','["C01","F03"]'::jsonb,11,'RECONCILE','change_in_AR == (closing_AR - opening_AR) adjusted for noncash_FX','MISSING_INPUT_CONTRACT','stock-to-flow bridge requires two pinned asOf snapshots','de698223e65c64ce887ee30796a658b2706278e5ff7469a257f06b8d779d35c3','docs/sources/FIN-CALC154-USER-FORMULA-RESEARCH-2026-11-20.md'),
 ('X_C02_F03','F03','["C02","F03"]'::jsonb,11,'RECONCILE','change_in_AP == (closing_AP - opening_AP) adjusted for noncash_FX','MISSING_INPUT_CONTRACT','liability stock-to-flow bridge requires two snapshots','de698223e65c64ce887ee30796a658b2706278e5ff7469a257f06b8d779d35c3','docs/sources/FIN-CALC154-USER-FORMULA-RESEARCH-2026-11-20.md'),
 ('X_C03_F03','F03','["C03","F03"]'::jsonb,11,'RECONCILE','inventory_movement == closing_inv - opening_inv adjusted for noncash','MISSING_INPUT_CONTRACT','cogs purchases and noncash adjustments require provenance','de698223e65c64ce887ee30796a658b2706278e5ff7469a257f06b8d779d35c3','docs/sources/FIN-CALC154-USER-FORMULA-RESEARCH-2026-11-20.md'),
 ('X_P04_P09','P09','["P04","P09"]'::jsonb,11,'RECONCILE','contractual_debt_service_P09 == cash_payments_P04 for same period','REQUIRES_FINANCIAL_POLICY','match same schedule version, fees and grace','de698223e65c64ce887ee30796a658b2706278e5ff7469a257f06b8d779d35c3','docs/sources/FIN-CALC154-USER-FORMULA-RESEARCH-2026-11-20.md'),
 ('X_P06_P01','P01','["P01","P02","P06"]'::jsonb,11,'RECONCILE','forecast_AR_P01 == DSO*recognized_revenue_P02 / basis_days','REQUIRES_FINANCIAL_POLICY','no simultaneous fixed-percentage and DSO assumptions','de698223e65c64ce887ee30796a658b2706278e5ff7469a257f06b8d779d35c3','docs/sources/FIN-CALC154-USER-FORMULA-RESEARCH-2026-11-20.md');
),
 related_form_codes_jsonb jsonb NOT NULL CHECK(jsonb_typeof(related_form_codes_jsonb)='array'),
 source_section smallint NOT NULL CHECK(source_section BETWEEN 1 AND 12),
 operation_family varchar(40) NOT NULL,
 formula_text text NOT NULL CHECK(length(trim(formula_text))>0),
 review_status varchar(40) NOT NULL CHECK(review_status IN
  ('MISSING_INPUT_CONTRACT','REQUIRES_FINANCIAL_POLICY',
   'CORRECTED_FROM_SOURCE','NON_EXECUTABLE_DISCLOSURE')),
 blockers_text text NOT NULL,
 uploaded_source_sha256 char(64) NOT NULL
   CHECK(uploaded_source_sha256 ~ '^[0-9a-f]{64}$'),
 source_repository_path text NOT NULL,
 financially_approved boolean NOT NULL DEFAULT false CHECK(NOT financially_approved),
 production_admitted boolean NOT NULL DEFAULT false CHECK(NOT production_admitted),
 created_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
CREATE INDEX idx_method_research_form
 ON fin_calc.methodology_research_candidate(owner_form_code,operation_family);
